     8	export function coerce(raw: string): ConfigValue {
     9	  const trimmed = raw.trim();
    10	  if (trimmed === "true") return true;
    11	  if (trimmed === "false") return false;
    12	  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
